"""Isolate FP32 drift on frozen inputs from the width-640 counterexample."""
import json
import sys
from pathlib import Path

import torch
import triton

from bio_inspired_nanochat.kernels import presyn_fused
from key_local_register import key_local_scan
from scan_edge_cases import NAMES, clone
from scan_model_holdout import call, ids, model
from scan_probe_live import use_kernel


class CaptureLaunch:
    def __init__(self, kernel, split_keys, fusion):
        self.kernel = kernel
        self.split_keys = split_keys
        self.fusion = fusion
        self.compiled = None

    def __getitem__(self, grid):
        def launch(*args, **kw):
            if self.split_keys:
                kw["BLOCK_KEYS"] = 4
                kw["NUM_TILES"] = triton.cdiv(kw["T_KEY"], 4)
                actual_grid = (*grid, kw["NUM_TILES"])
            else:
                actual_grid = grid
            self.compiled = self.kernel[actual_grid](
                *args, num_warps=4, enable_fp_fusion=self.fusion, **kw,
            )
            return self.compiled
        return launch


def bit_difference(left, right):
    delta = ~torch.eq(left.contiguous().view(torch.int32),right.contiguous().view(torch.int32))
    where = delta.nonzero()
    return {"bitwise_mismatches":len(where),"first":where[0].tolist() if len(where) else None,
            "max_abs":(left-right).abs().max().item()}


def select_inputs():
    saved = []
    original = presyn_fused.presyn_detached_scan

    def record(state, drive, idx, valid, cfg, **kw):
        if len(saved) < 2:
            saved.append((clone(state), drive.clone(), idx.clone(), valid.clone(), cfg, kw))
        return original(state,drive,idx,valid,cfg,**kw)

    presyn_fused.presyn_detached_scan = record
    try:
        call(model(True),ids(88292,128))
    finally:
        presyn_fused.presyn_detached_scan = original
    assert len(saved) == 2
    return saved


def compare(root):
    baseline = presyn_fused.presyn_detached_scan_kernel
    variants = {
        "incumbent": CaptureLaunch(baseline,False,True),
        "register": CaptureLaunch(key_local_scan,True,True),
        "incumbent_no_fma": CaptureLaunch(baseline,False,False),
        "register_no_fma": CaptureLaunch(key_local_scan,True,False),
    }
    rows = []
    for state0,drive,idx,valid,cfg,kw in select_inputs():
        first = kw["first_active_key_count"]
        outputs = {}
        for name,launch in variants.items():
            state = clone(state0)
            with use_kernel(launch):
                exposed,_,_ = presyn_fused.presyn_detached_scan(state,drive,idx,valid,cfg,**kw)
            outputs[name] = {"release":exposed,**{key:state[key] for key in NAMES},
                             **{f"delay_{slot}":v for slot,v in enumerate(state["DELAY"])}}
            for form in ("ptx","llir"):
                with (root / f"{name}_{first}.{form}").open("x",encoding="utf-8") as stream:
                    stream.write(launch.compiled.asm[form])
        rows.append({
            "first_active":first,
            "by_pair":{
                f"{a}__{b}":{field:bit_difference(left,outputs[b][field]) for field,left in outputs[a].items()}
                for a,b in (("incumbent","register"),("incumbent_no_fma","register_no_fma"),
                            ("incumbent","incumbent_no_fma"),("incumbent","register_no_fma"))
            },
        })
        print(json.dumps(rows[-1]),flush=True)
    assert any(row["by_pair"]["incumbent__register"]["release"]["bitwise_mismatches"] for row in rows)
    return rows


if __name__ == "__main__":
    root = Path(sys.argv[1])
    with torch.inference_mode():
        report = compare(root)
    with (root / "arithmetic.json").open("x",encoding="utf-8") as stream:
        json.dump(report,stream,indent=2,sort_keys=True,allow_nan=False)
        stream.write("\n")
